SKIP_NAMES = {"_brief.md", "_recalc_brief.md"}
NUM_RE = re.compile(r"\d+(?:\.\d+)?")
EV_RE = re.compile(r"[；，、]?\s*[^（）()；。\s]*\.md:\d[\d,\-–\s]*")   # 与 generate_results.EV_RE 同源
EVREF_RE = re.compile(r"[^\s；，、|]*\.md:\d[\d,\-–\s]*")
DOCREF_RE = re.compile(r"(?:\d\d-[\w一-鿿]+\.md|docs/[\w\-]+\.md|_brief\.md|\S+/攻击范围\.md)")
BANNED = ((re.compile(r"(?<![0-9])★"), "★ 分类标记"),
          (re.compile(r"备注[:：]"), "「备注：」字样"),
          (re.compile(r"PRTS\s?(?:备注|注)[:：]"), "「PRTS 备注」字样"),
          (re.compile(r"(?:天赋|技能)原文[:：]"), "「原文」字样"),
          (re.compile(r"(?<![A-Za-z])S[123](?![0-9])"), "裸 S1/S2/S3"))
BARE_SKILL_RE = re.compile(r"[0-9一二三]技能")


def head_text(rel: str) -> str | None:
    r = subprocess.run(["git", "show", f"HEAD:{rel}"], cwd=ROOT, capture_output=True)
    return r.stdout.decode("utf-8") if r.returncode == 0 else None


def table_rows(text: str) -> dict[str, list[tuple[str, str, str]]]:
    """成员表 → {干员: [(条件, 备注, 依据), …]}（按出现顺序）；非成员表（表头无「条件」「备注」列）跳过。

    表头以「其后紧跟分隔行（|---|…）」判定——**每张表各自判定**：非成员表（如边界与排除
    记录的表）会把列头置空、其行不再误读为成员行（旧版沿用上一张成员表的列头、把边界表按
    五列硬解成「行」，追加新同名行时会与它们错配）。同名多行（同一干员分属多个子表，或后续
    追加的新子表）按出现顺序全部保留——审计据此**按序配对**（见 main）。
    """
    out: dict[str, list[tuple[str, str, str]]] = {}
    header: list[str] | None = None
    lines = [l for l in text.splitlines() if l.startswith("|")]
    for i, line in enumerate(lines):
        cells = [c.strip() for c in line.split("|")[1:-1]]
        nxt = [c.strip() for c in lines[i + 1].split("|")[1:-1]] if i + 1 < len(lines) else []
        if nxt and set("".join(nxt)) <= set("-: "):        # 本行是表头：看它是不是成员表
            header = cells if ("条件" in cells and "备注" in cells) else None
            continue
        if header is None or len(cells) != len(header) or set("".join(cells)) <= set("-: "):
            continue
        ci, ni = header.index("条件"), header.index("备注")
        ref = cells[header.index("依据")] if "依据" in header else ""
        out.setdefault(cells[0].replace("**", "").strip(), []).append((cells[ci], cells[ni], ref))
    return out


def numbers(cell: str) -> set[str]:
    """数字令牌；先摘掉 `文件:行号` 证据（行号会随排版移动，不算内容）。"""
    return set(NUM_RE.findall(EV_RE.sub("", cell)))


def main() -> int:
    ap = argparse.ArgumentParser(description="条件/备注重排的守恒审计")
    ap.add_argument("--only", default="", help="只审文件名含该串的文件")
    args = ap.parse_args()

    n_rows = n_changed = 0
    lost_num: list[str] = []
    lost_ref: list[str] = []
    banned: list[str] = []
    shape: list[str] = []
    accepted: list[str] = []
    bare_skill: list[str] = []
    for folder in SCAN:
        for path in sorted((ROOT / folder).glob("*.md")):
            if path.name in SKIP_NAMES or (args.only and args.only not in path.name):
                continue
            rel = path.relative_to(ROOT).as_posix()
            old_text = head_text(rel)
            if old_text is None:
                continue
            old, new = table_rows(old_text), table_rows(path.read_text(encoding="utf-8"))
            for op, new_list in new.items():
              old_list = old.get(op, [])
              for idx, (ncond, nnote, nref) in enumerate(new_list):
                n_rows += 1
                if idx >= len(old_list):   # 新增行（HEAD 无对应出现序）：不属重排审计范围
                    continue
                ocond, onote, oref = old_list[idx]
                if (ocond, onote) == (ncond, nnote):
                    continue
                n_changed += 1
                where = f"{path.name}｜{op}"
                allow, why = ACCEPTED.get(f"{path.name}｜{op}", (set(), ""))
                miss = numbers(ocond + onote) - numbers(ncond + nnote) - allow
                if miss:
                    lost_num.append(f"{where}：{sorted(miss)}")
                elif allow & (numbers(ocond + onote) - numbers(ncond + nnote)):
                    accepted.append(f"{where}：{why}")
                if set(EVREF_RE.findall(oref)) - set(EVREF_RE.findall(nref)):
                    lost_ref.append(where)
                for pattern, what in BANNED:
                    if pattern.search(nnote):
                        banned.append(f"{where}：{what}")
                        break
                for block in nnote.split("｜"):
                    label = block.split("：", 1)[0].strip() if "：" in block else ""
                    if BARE_SKILL_RE.fullmatch(label) and "「" not in block.split("：", 1)[1][:6]:
                        bare_skill.append(f"{where}：块标签「{label}」")
                        break
                want = len([s for s in split_top(nnote, "｜") if s.strip()])
                got = len(parse_blocks(nnote))
                if want != got:
                    shape.append(f"{where}：源文 {want} 块 / 解析 {got} 块")

    def report(title: str, items: list[str], fatal: bool) -> None:
        mark = "❌" if (items and fatal) else ("⚠" if items else "✓")
        print(f"{mark} {title}：{len(items)}")
        limit = len(items) if os.environ.get("AUDIT_ALL") else 30   # AUDIT_ALL=1：全量打印（登记放行表用）
        for x in items[:limit]:
            print("   " + x)
        if len(items) > limit:
            print(f"   …另有 {len(items) - limit} 条")

    print(f"对比 HEAD：{n_rows} 行成员，其中重排过 {n_changed} 行\n")
    report("数字丢失（应为 0）", lost_num, True)
    report("依据丢失（应为 0）", lost_ref, True)
    report("已放行的有意改动（ACCEPTED）", accepted, False)
    report("重排行残留禁用项（应为 0）", banned, False)
    report("重排行块标签未点名技能（应为 0）", bare_skill, False)
    report("重排行结构未生效（应为 0）", shape, False)
    return 1 if (lost_num or lost_ref) else 0


if __name__ == "__main__":
    raise SystemExit(main())